const englishRadialLabels={"径向极大":"Radial maximum","径向极小":"Radial minimum"};
import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls,resultHTML as baseResult,bindResult as bindBase} from './bridges-views.js?v=20261110-en1';
export {esc,num,table,notes,sources,readControls};
export function controlsHTML(module,values){const keys=module.id==='order'?['etaX','etaY','etaZ','basisAngle']:module.id==='exchange'?['dz','conventionAngle']:['fieldZ','gammaPhi','basisAngle'];return baseControls({...module,fields:module.fields.map(f=>f.type==='number'&&f.key!=='points'?{...f,step:'any'}:f)},values)+`<details class="pr-sliders"><summary>Drag parameters to compare</summary><p>Drag to synchronize the input above; click Calculate to update the result.</p>${module.fields.filter(f=>keys.includes(f.key)).map(f=>`<label>${esc(f.label)}<input type="range" data-pr-control="${esc(f.key)}" min="${f.min??-5}" max="${f.max??5}" step="${f.step??.1}" value="${esc(values[f.key])}"></label>`).join('')}</details>`;}
const value=x=>typeof x==='number'?num(x):x===null||x===undefined?'—':typeof x==='object'?JSON.stringify(x):(englishRadialLabels[x]||String(x));
const label=k=>({generator:"generator",operation:"Operation",formula:"constraint equation",relations:"coefficient relationship",inputResidual:"residual before projection",outputResidual:"residual after projection",degree:"polynomial degree",relation:"constraint relationship",matrix:"matrix",rotation:"coordinate transformation matrix",vector:"Order-parameter coordinates",tensor:"exchange tensor",D:"D vector",levels:"energy level",energyResidual:"energy spectrum difference",residual:"invariant residuals",retained:"Keep this order parameter",fieldRetained:"Preserves the external field",label:"Name",id:"logo",energy:"Energy",selected:"current diagnosis"})[k]||k;
const moreLabels={polarMatrix:"polar vector transformation matrix",axialMatrix:"axial vector transformation matrix",swapsSites:"Whether to exchange two endpoints",hamiltonianNorm:"Hamiltonian commutation subnorm",totalAdjointNorm:"complete companion generator action norm",dissipatorNorm:"dissipation contribution norm",hamiltonianConserved:"The closed system is conserved for all initial states",conserved:"Complete dynamics conserved for all initial states",commutator:"commutation submatrix",totalAdjoint:"Complete accompanying action matrix",contributions:"Hamiltonian contributions",channels:"Contribution of each dissipation channel",term:"action item",coefficient:"Coefficients",norm:"matrix norm",channel:"dissipation channel",re:"real part",im:"imaginary part",timeReversalSquare:"time reversal square",timeReversalResidual:"time reversal residual",timeReversalSymmetric:"whether to retain time reversal",kramersProtected:"have Kramers protection?",squareResidual:"Inverse unitary square residual",multiplicity:"numerical degeneracy",explanation:"Explain",interpretation:"physical explanation",angleDegrees:"angle (degrees)",axis:"rotation axis",definition:"Conventional definition",swapSites:"exchange endpoint tag",original:"original agreement",transformed:"New Agreement",energyResidual:"energy spectrum difference",expectationResidual:"Expected value difference",stateResidual:"state evolution covariance residual",adjointResidual:"accompanying effects covariance residual",spin1:"The first classical spin direction",spin2:"The second classical spin direction",singularValues:"Exchange tensor singular values",convention:"usage convention",statement:"Conclusion",hamiltonian:'Hamiltonian',observable:"observation operator",initialState:"Initial state",unitary:"change of basis matrix",D:"D vector"};
Object.assign(moreLabels,{sourcePowers:"The degree of each component of the original monomial",targetPowers:"The degree of each component of the monomial after transformation",sign:"transformation symbol",rule:"transformation rules",field:"field coordinates",operations:"Group operation after transformation",covarianceResidual:"covariance residual",description:"Notes",operator:"Generator matrices",adjoint:"Complete accompanying action matrix",trivial:"a trivial constant operator?",factor:"matrix element",globalSU2:"Hamiltonian have global SU(2) symmetry?",reason:"Judgment basis",scope:"Scope",eigenvalues:"All eigenvalues",timeReversalUnitary:"Unitary part of time reversal",originalHamiltonian:"formerly Hamiltonian",transformedHamiltonian:"Hamiltonian after the basis change",originalObservable:"original observation operator",transformedObservable:"change of basis",maximumMultiplicity:"multiplicity with maximum singular value",angleDegrees:"included angle (degrees)"});
const title=k=>moreLabels[k]||label(k);
function detail(x,depth=0){if(Array.isArray(x)&&x.length&&x.every(r=>Array.isArray(r)&&r.every(v=>typeof v!=='object')))return table(x[0].map((_,i)=>"column "+i),x.map(r=>r.map(value)));if(x&&typeof x==='object'){const entries=Object.entries(x),simple=entries.filter(([,v])=>!v||typeof v!=='object'),nested=entries.filter(([,v])=>v&&typeof v==='object');return (simple.length?table(["project","results"],simple.map(([k,v])=>[title(k),typeof v==='boolean'?(v?"Yes":"No"):value(v)])):'')+nested.map(([k,v])=>`<details${depth===0?' open':''}><summary>${esc(Array.isArray(x)?"No. "+(Number(k)+1)+" item":title(k))}</summary>${depth<4?detail(v,depth+1):`<pre>${esc(JSON.stringify(v,null,2))}</pre>`}</details>`).join('');}return `<p>${esc(value(x))}</p>`;}
function vectorSVG(vectors){const project=([x=0,y=0,z=0])=>[300+100*x-45*y,170-100*z+40*y];const max=Math.max(1,...vectors.flatMap(v=>v.vector||[]).map(Math.abs));return `<svg viewBox="0 0 600 350" role="img" aria-label="vector in model coordinates; the projected length is for illustration only"><defs><marker id="pr-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3z" fill="#277a64"/></marker></defs>${[[1.6,0,0,'x'],[0,1.6,0,'y'],[0,0,1.4,'z']].map(p=>{const e=project(p);return `<path d="M300 170L${e[0]} ${e[1]}" stroke="#a0b2a6"/><text x="${e[0]}" y="${e[1]-8}">${p[3]}</text>`;}).join('')}${vectors.map((v,i)=>{const q=project(v.vector.map(x=>x/max));return `<path d="M300 170L${q[0]} ${q[1]}" stroke="${i?'#b27c31':'#277a64'}" stroke-width="4" marker-end="url(#pr-arrow)"/><text x="${q[0]+10}" y="${q[1]+i*20}">${esc(v.label)}</text>`;}).join('')}</svg>`;}
function proofRows(module,r){return module==='order'?r.order?.constraintSources||[]:module==='exchange'?r.exchange?.constraints||[]:r.conservation?.proofs||[];}
export function resultHTML(module,r){const rows=proofRows(module,r),ops=r.order?.operations||[];return `<section class="pr-evidence"><h3>constraint source derivation</h3><p>Select a constraint to check the actual transformation, coefficient relationship, or generator effect; symmetry allows terms that can still be zero due to parameter values.</p><label>View derivation<select id="pr-proof">${rows.map((x,i)=>`<option value="${i}">${esc(x.label||x.generator||x.operation||x.name||x.id||"constraint "+(i+1))}</option>`).join('')}</select></label><div id="pr-proof-info"></div></section>${module==='order'?`<section class="pr-evidence"><h3>order parameter and retention operations</h3><label>group element acting<select id="pr-operation">${ops.map((x,i)=>`<option value="${i}">${esc(x.label||x.id)} · ${x.retained?"Retained":"change"}direction</option>`).join('')}</select></label><div id="pr-operation-info"></div><div id="pr-vector"></div><p>Arrow display order parameter represents space and is not automatically equivalent to atomic displacement in a real crystal.</p></section>`:''}${module==='exchange'?"<section class=\"pr-evidence\"><h3>Exchange tensor and spin direction</h3><div id=\"pr-spin\"></div><div id=\"pr-spin-info\"></div></section>":''}<section class="pr-evidence"><h3>Conventional comparison: compare after consistent transformation</h3><p>The result comes from the coordinate or base transformation of the current input, transforming both the operator and the state. Recalculate after modifying the agreed parameters above.</p><div id="pr-convention"></div></section>${module==='conservation'?"<section class=\"pr-evidence\"><h3>degeneracy protection Diagnosis</h3><p>First check the inverse unitary symmetry and squareness, and then determine whether the energy level degeneracy is protected by this model time reversal .</p><div id=\"pr-degeneracy\"></div></section>":''}${baseResult('',r)}`;}
export function bindResult(module,r,root){bindBase('',r,root);const $=s=>root.querySelector(s),rows=proofRows(module,r),draw=()=>{$('#pr-proof-info').innerHTML=detail(rows[Number($('#pr-proof').value)]||"currently has no independent constraints.");};$('#pr-proof').onchange=draw;draw();$('#pr-convention').innerHTML=detail(r.order?.convention||r.convention||r.conservation?.convention);
 if(module==='order'){const drawOp=()=>{const o=r.order.operations[Number($('#pr-operation').value)],v=r.order.vector,t=o.matrix.map(row=>row.reduce((s,x,i)=>s+x*v[i],0));$('#pr-operation-info').innerHTML=detail({operation:o.label||o.id,vector:t,retained:o.retained,fieldRetained:o.fieldRetained});$('#pr-vector').innerHTML=vectorSVG([{label:'η',vector:v},{label:'D(g)η',vector:t}]);};$('#pr-operation').onchange=drawOp;drawOp();}
 if(module==='exchange'){$('#pr-spin').innerHTML=vectorSVG([{label:'D',vector:r.exchange.D},{label:'S₁',vector:r.classical.spin1},{label:'S₂',vector:r.classical.spin2}]);$('#pr-spin-info').innerHTML=detail(r.classical);}
 if(module==='conservation')$('#pr-degeneracy').innerHTML=detail(r.conservation.degeneracy);
}
